#!/usr/bin/env node

/**
 * Build a fail-closed BitterClip Artifact release packet for one or more baked
 * ISO4 delivery variants.
 *
 * This is a local packaging tool. It does not publish, accept, deploy, start a
 * server, or edit application source. Every generated byte stays below tmp/.
 * The release packet matches BitterClip's strict
 * `bitterclip.artifact_release_packet.v1` operator schema.
 *
 * Example:
 *   node qa/iso4-artifact-packet.mjs \
 *     --bake-receipt tmp/iso4-release/wide/release-receipt.json \
 *     --encode-receipt tmp/iso4-release/wide/encodes/encode-receipt.json \
 *     --crf 18 \
 *     --account-public-id acct_00000000000000000000 \
 *     --profile wide \
 *     --poster-profile lossless \
 *     --source-file app/app.vue \
 *     --source-file app/assets/css/main.css \
 *     --source-file app/components/HeroIso4.vue \
 *     --source-file app/layouts/default.vue \
 *     --source-file app/lib/hero-iso4/scene.ts \
 *     --source-file app/pages/index.vue \
 *     --media-file public/clips/ep1-john.jpg \
 *     --media-file public/clips/ep1-john2.jpg \
 *     --media-file public/clips/ep1-loop.mp4 \
 *     --media-file public/clips/ep1-michael.jpg \
 *     --dependency-file bun.lock \
 *     --dependency-file nuxt.config.ts \
 *     --dependency-file package.json \
 *     --dependency-file qa/iso4-artifact-bake.mjs \
 *     --dependency-file qa/iso4-artifact-encode.mjs \
 *     --dependency-file qa/iso4-artifact-packet.mjs \
 *     --dependency-file qa/iso4-artifact-provenance.mjs \
 *     --output tmp/iso4-release/wide/release-packet
 */

import { createHash } from 'node:crypto'
import { once } from 'node:events'
import { constants as fsConstants, createReadStream } from 'node:fs'
import {
  access,
  copyFile,
  lstat,
  mkdir,
  readFile,
  rename,
  rm,
  stat,
  writeFile,
} from 'node:fs/promises'
import { basename, dirname, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { gzipSync, gunzipSync } from 'node:zlib'
import { spawn } from 'node:child_process'
import {
  ISO4_REQUIRED_RENDERER_INPUTS,
  rendererInputReceiptFromEntries,
  validateRendererInputReceipt,
} from './iso4-artifact-provenance.mjs'

const SCRIPT_VERSION = 'iso4-artifact-packet/v2'
const REPO_ROOT = fileURLToPath(new URL('..', import.meta.url))
const TMP_ROOT = resolve(REPO_ROOT, 'tmp')
const RELEASE_SCHEMA = 'bitterclip.artifact_release_packet.v1'
const GENERATION_SCHEMA = 'bitterclip.artifact_generation_manifest.v1'
const SOURCE_BUNDLE_SCHEMA = 'bitterclip.iso4-source-bundle.v1'
const MARKETING_SCHEMA = 'bitterclip.programmable_artifact_generation.v1'
const VARIANT_SPEC_SCHEMA = 'bitterclip.iso4-artifact-variant-spec.v1'
const ACCOUNT_PATTERN = /^acct_[a-z0-9]{20}$/
const NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,95}$/
const COMPONENT_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$/
const SHA256_PATTERN = /^[a-f0-9]{64}$/
const MAX_PACKET_BYTES = 1024 * 1024
const MAX_BUNDLE_INPUT_BYTES = 1024 * 1024 * 1024
const MAX_VARIANT_PROFILE_CHARS = 87
const SECRET_TEXT_PATTERN = /(?:-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|AKIA[0-9A-Z]{16}|github_pat_[A-Za-z0-9_]{20,}|ghp_[A-Za-z0-9]{20,}|(?:password|secret|token|api[-_]?key)\s*[:=]\s*\S+)/i

const PROFILE_CONTRACTS = Object.freeze({
  mobile: { width: 440, height: 956, media: '(max-width: 599px)' },
  tablet: { width: 768, height: 900, media: '(min-width: 600px) and (max-width: 959px)' },
  tall: { width: 1818, height: 1454, media: '(min-width: 960px) and (max-aspect-ratio: 4/3)' },
  classic: { width: 1400, height: 1000, media: '(min-width: 960px) and (min-aspect-ratio: 4/3) and (max-aspect-ratio: 3/2)' },
  standard: { width: 1600, height: 1000, media: '(min-width: 960px) and (min-aspect-ratio: 3/2) and (max-aspect-ratio: 17/10)' },
  wide: { width: 1600, height: 900, media: '(min-width: 960px) and (min-aspect-ratio: 17/10) and (max-aspect-ratio: 29/16)' },
  panoramic: { width: 1728, height: 936, media: '(min-width: 960px) and (min-aspect-ratio: 29/16) and (max-aspect-ratio: 2/1)' },
  ultrawide: { width: 1920, height: 900, media: '(min-width: 960px) and (min-aspect-ratio: 2/1)' },
  'wide-band': { width: 1920, height: 900, media: '(min-width: 960px) and (min-aspect-ratio: 17/10)' },
})

const usage = `Usage:
  node qa/iso4-artifact-packet.mjs [required options]

Required:
  --account-public-id ID    BitterClip account public ID (acct_ + 20 chars)
  --output DIR              New dedicated output directory below tmp/
  --source-file PATH        Repeat for authored ISO4 source files
  --media-file PATH         Repeat for source media; must include bake source
  --dependency-file PATH    Repeat for renderer/dependency inputs

Options:
  --variant-spec PATH       Strict 1-8 variant JSON under tmp/. Replaces the
                            single-profile bake/encode/selection options.
  --bake-receipt PATH       Complete bake receipt (single-profile mode)
  --encode-receipt PATH     Encode receipt (single-profile mode)
  --crf 15|18|21            Select by CRF (single-profile mode)
  --candidate PATH          Select exact candidate path (single-profile mode)
  --profile NAME            Variant/profile key (default: wide)
  --media-query QUERY       Required for unknown profiles; known profiles use
                            the production HeroIso4 media query
  --poster-profile MODE     Published poster candidate: q92 or lossless
                            (default: lossless); both are always generated
  --definition-key KEY      Artifact definition key (default: homepage-iso4)
  --definition-name NAME    Definition display name
  --definition-description TEXT
  --source-revision VALUE   Optional Git/audit label; excluded from the
                            cinematic generation fingerprint
  --renderer-key VALUE      Renderer key (default: iso4.playwright)
  --renderer-version VALUE  Renderer version; defaults from bake script version
  --expected-acceptance-version N
                            Include explicit compare-and-swap acceptance
  --ffmpeg PATH             ffmpeg binary (default: ffmpeg)
  --ffprobe PATH            ffprobe binary (default: ffprobe)
  --cwebp PATH              cwebp binary (default: cwebp)
  --self-test               Run strict in-memory contract tests only
  --help                    Show this message

Without --variant-spec, bake receipt, encode receipt, and exactly one of CRF or
candidate are required. A variant spec has this exact shape:

  { "schema": "${VARIANT_SPEC_SCHEMA}", "variants": [
    { "profile": "wide", "media_query": "(...) ",
      "bake_receipt": "...", "encode_receipt": "...", "crf": 18 }
  ] }

Use candidate instead of crf to select an exact candidate path. Spec-relative
paths resolve beside the spec. All declared bundle inputs must be regular,
non-symlink files inside this repository and outside tmp/. The declarations
must exactly cover the canonical ISO4 renderer-input set; no file may be
omitted or added. Existing output is never overwritten.`

function parseCli(argv) {
  if (argv.includes('--help') || argv.includes('-h')) return { help: true }
  if (argv.includes('--self-test')) {
    if (argv.length !== 1) throw new Error('--self-test cannot be combined with other options')
    return { selfTest: true }
  }
  const options = {
    provided: new Set(),
    sourceFiles: [],
    mediaFiles: [],
    dependencyFiles: [],
    profile: 'wide',
    posterProfile: 'lossless',
    definitionKey: 'homepage-iso4',
    definitionName: 'ISO4 homepage cinematic',
    definitionDescription: 'Public BitterClip sample artifact.',
    rendererKey: 'iso4.playwright',
    ffmpeg: process.env.FFMPEG_BIN || 'ffmpeg',
    ffprobe: process.env.FFPROBE_BIN || 'ffprobe',
    cwebp: process.env.CWEBP_BIN || 'cwebp',
  }
  const scalar = new Map([
    ['--bake-receipt', 'bakeReceipt'],
    ['--encode-receipt', 'encodeReceipt'],
    ['--crf', 'crf'],
    ['--candidate', 'candidate'],
    ['--variant-spec', 'variantSpec'],
    ['--account-public-id', 'accountPublicId'],
    ['--output', 'output'],
    ['--profile', 'profile'],
    ['--media-query', 'mediaQuery'],
    ['--poster-profile', 'posterProfile'],
    ['--definition-key', 'definitionKey'],
    ['--definition-name', 'definitionName'],
    ['--definition-description', 'definitionDescription'],
    ['--source-revision', 'sourceRevision'],
    ['--renderer-key', 'rendererKey'],
    ['--renderer-version', 'rendererVersion'],
    ['--expected-acceptance-version', 'expectedAcceptanceVersion'],
    ['--ffmpeg', 'ffmpeg'],
    ['--ffprobe', 'ffprobe'],
    ['--cwebp', 'cwebp'],
  ])
  const repeated = new Map([
    ['--source-file', 'sourceFiles'],
    ['--media-file', 'mediaFiles'],
    ['--dependency-file', 'dependencyFiles'],
  ])
  for (let index = 0; index < argv.length; index++) {
    const argument = argv[index]
    const scalarKey = scalar.get(argument)
    const repeatedKey = repeated.get(argument)
    if (!scalarKey && !repeatedKey) throw new Error(`unknown argument: ${argument}\n\n${usage}`)
    const value = argv[++index]
    if (!value || value.startsWith('--')) throw new Error(`${argument} requires a value`)
    if (scalarKey) {
      if (Object.hasOwn(options, scalarKey) && !['profile', 'posterProfile', 'definitionKey', 'definitionName', 'definitionDescription', 'rendererKey', 'ffmpeg', 'ffprobe', 'cwebp'].includes(scalarKey)) {
        throw new Error(`${argument} may only be supplied once`)
      }
      options[scalarKey] = value
      options.provided.add(scalarKey)
    } else {
      options[repeatedKey].push(value)
    }
  }
  return options
}

function isInside(parent, child) {
  const prefix = parent.endsWith(sep) ? parent : `${parent}${sep}`
  return child === parent || child.startsWith(prefix)
}

async function exists(path) {
  try {
    await access(path)
    return true
  } catch {
    return false
  }
}

function commandText(command, args) {
  return [command, ...args].map((part) => JSON.stringify(String(part))).join(' ')
}

async function run(command, args, { binary = false } = {}) {
  const child = spawn(command, args, {
    cwd: REPO_ROOT,
    env: process.env,
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  const stdout = []
  const stderr = []
  child.stdout.on('data', (chunk) => stdout.push(chunk))
  child.stderr.on('data', (chunk) => stderr.push(chunk))
  child.on('error', (error) => {
    // Without this listener an unavailable codec binary terminates Node before
    // the caller can report a clean fail-closed error.
    child.__spawnError = error
  })
  const [code, signal] = await once(child, 'close')
  const stdoutBuffer = Buffer.concat(stdout)
  const stderrText = Buffer.concat(stderr).toString('utf8')
  if (child.__spawnError) throw child.__spawnError
  if (code !== 0) {
    throw new Error(`${commandText(command, args)} failed (${signal || code})\n${stderrText || stdoutBuffer.toString('utf8')}`)
  }
  return { stdout: binary ? stdoutBuffer : stdoutBuffer.toString('utf8'), stderr: stderrText }
}

async function sha256(path) {
  const hash = createHash('sha256')
  const stream = createReadStream(path)
  stream.on('data', (chunk) => hash.update(chunk))
  await once(stream, 'end')
  return hash.digest('hex')
}

function sha256Buffer(buffer) {
  return createHash('sha256').update(buffer).digest('hex')
}

async function exactRegularFile(path, { inside = null } = {}) {
  const absolute = resolve(path)
  if (inside && !isInside(inside, absolute)) throw new Error(`file is outside ${inside}: ${absolute}`)
  const info = await lstat(absolute)
  if (!info.isFile() || info.isSymbolicLink()) throw new Error(`expected one regular non-symlink file: ${absolute}`)
  if (info.size < 1) throw new Error(`file is empty: ${absolute}`)
  return { path: absolute, bytes: info.size }
}

async function readJsonFile(path, label) {
  const file = await exactRegularFile(path)
  let parsed
  try {
    parsed = JSON.parse(await readFile(file.path, 'utf8'))
  } catch {
    throw new Error(`${label} is not valid JSON: ${file.path}`)
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`${label} must be one JSON object`)
  }
  return { file, parsed }
}

function strictObject(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${label} must be one JSON object`)
  }
  return value
}

function rejectUnknownKeys(value, allowed, label) {
  const unknown = Object.keys(value).filter((key) => !allowed.includes(key))
  if (unknown.length) throw new Error(`${label} contains unknown keys: ${unknown.sort().join(', ')}`)
}

function specRelativePath(value, specPath, label) {
  if (typeof value !== 'string' || !value || /[\u0000-\u001f\u007f]/.test(value)) {
    throw new Error(`${label} must be one clean path string`)
  }
  const resolved = resolve(dirname(specPath), value)
  if (!isInside(TMP_ROOT, resolved)) throw new Error(`${label} must resolve under tmp/`)
  return resolved
}

function normalizeVariantSpecDocument(document, specPath) {
  const value = strictObject(document, 'variant spec')
  rejectUnknownKeys(value, ['schema', 'variants'], 'variant spec')
  if (value.schema !== VARIANT_SPEC_SCHEMA) throw new Error('unsupported variant spec schema')
  if (!Array.isArray(value.variants) || !value.variants.length || value.variants.length > 8) {
    throw new Error('variant spec must contain 1-8 variants')
  }
  const variants = value.variants.map((raw, index) => {
    const variant = strictObject(raw, `variant spec entry ${index}`)
    rejectUnknownKeys(
      variant,
      ['profile', 'media_query', 'bake_receipt', 'encode_receipt', 'crf', 'candidate'],
      `variant spec entry ${index}`,
    )
    if (!NAME_PATTERN.test(String(variant.profile ?? '')) || variant.profile.length > MAX_VARIANT_PROFILE_CHARS) {
      throw new Error(`variant spec entry ${index} has an invalid profile`)
    }
    if (typeof variant.media_query !== 'string' || !variant.media_query.trim()
      || Buffer.byteLength(variant.media_query) > 4096
      || /[\u0000-\u001f\u007f]/.test(variant.media_query)) {
      throw new Error(`variant spec entry ${index} has an invalid media_query`)
    }
    if ((variant.crf === undefined) === (variant.candidate === undefined)) {
      throw new Error(`variant spec entry ${index} requires exactly one of crf or candidate`)
    }
    let selection
    if (variant.crf !== undefined) {
      if (![15, 18, 21].includes(variant.crf)) {
        throw new Error(`variant spec entry ${index} crf must be the number 15, 18, or 21`)
      }
      selection = { crf: variant.crf }
    } else {
      selection = { candidate: specRelativePath(variant.candidate, specPath, `variant spec entry ${index} candidate`) }
    }
    return {
      index,
      profile: variant.profile,
      mediaQuery: variant.media_query.trim(),
      bakeReceipt: specRelativePath(variant.bake_receipt, specPath, `variant spec entry ${index} bake_receipt`),
      encodeReceipt: specRelativePath(variant.encode_receipt, specPath, `variant spec entry ${index} encode_receipt`),
      selection,
    }
  })
  const profiles = variants.map((variant) => variant.profile)
  const mediaQueries = variants.map((variant) => variant.mediaQuery)
  if (new Set(profiles).size !== profiles.length) throw new Error('variant spec contains duplicate profiles')
  if (new Set(mediaQueries).size !== mediaQueries.length) throw new Error('variant spec contains duplicate media queries')
  for (const [label, values] of [
    ['bake receipts', variants.map((variant) => variant.bakeReceipt)],
    ['encode receipts', variants.map((variant) => variant.encodeReceipt)],
  ]) {
    if (new Set(values).size !== values.length) throw new Error(`variant spec contains duplicate ${label}`)
  }
  return variants
}

async function loadVariantInputs(options) {
  if (!options.variantSpec) {
    const profileContract = PROFILE_CONTRACTS[options.profile]
    const mediaQuery = String(options.mediaQuery || profileContract?.media || '').trim()
    if (!mediaQuery) throw new Error('--media-query is required for an unknown profile')
    if (Buffer.byteLength(mediaQuery) > 4096 || /[\u0000-\u001f\u007f]/.test(mediaQuery)) {
      throw new Error('--media-query is invalid')
    }
    return {
      mode: 'single',
      spec: null,
      variants: [{
        index: 0,
        profile: options.profile,
        mediaQuery,
        bakeReceipt: resolve(options.bakeReceipt),
        encodeReceipt: resolve(options.encodeReceipt),
        selection: { crf: options.crf, candidate: options.candidate },
      }],
    }
  }
  const specPath = resolve(options.variantSpec)
  const { file, parsed } = await readJsonFile(specPath, 'variant spec')
  if (!isInside(TMP_ROOT, file.path)) throw new Error('--variant-spec must be under tmp/')
  if (file.bytes > 256 * 1024) throw new Error('variant spec exceeds 256 KiB')
  return {
    mode: 'multi',
    spec: { path: file.path, bytes: file.bytes, sha256: await sha256(file.path) },
    variants: normalizeVariantSpecDocument(parsed, file.path),
  }
}

async function probe(path, ffprobe, { countFrames = false } = {}) {
  const { stdout } = await run(ffprobe, [
    '-v', 'error',
    ...(countFrames ? ['-count_frames'] : []),
    '-show_streams',
    '-show_format',
    '-of', 'json',
    path,
  ])
  return JSON.parse(stdout)
}

function fraction(value) {
  const [numerator, denominator = '1'] = String(value || '0').split('/').map(Number)
  return denominator ? numerator / denominator : 0
}

async function fastStart(path) {
  const bytes = await readFile(path)
  const moovOffset = bytes.indexOf(Buffer.from('moov'))
  const mdatOffset = bytes.indexOf(Buffer.from('mdat'))
  return { moovOffset, mdatOffset, valid: moovOffset > 0 && mdatOffset > 0 && moovOffset < mdatOffset }
}

function assertSha256(value, label) {
  if (!SHA256_PATTERN.test(String(value))) throw new Error(`${label} is not a lowercase SHA-256 digest`)
  return String(value)
}

async function verifyReceiptFile(entry, label, { inside = null } = {}) {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) throw new Error(`${label} receipt is missing`)
  const file = await exactRegularFile(entry.path, { inside })
  const expectedBytes = Number(entry.bytes)
  if (!Number.isSafeInteger(expectedBytes) || expectedBytes !== file.bytes) {
    throw new Error(`${label} byte size does not match its receipt`)
  }
  const expectedHash = assertSha256(entry.sha256, `${label}.sha256`)
  const actualHash = await sha256(file.path)
  if (actualHash !== expectedHash) throw new Error(`${label} SHA-256 does not match its receipt`)
  return { ...file, sha256: actualHash }
}

function countFrames(video) {
  const raw = video?.nb_read_frames ?? video?.nb_frames
  const frames = Number(raw)
  if (!Number.isInteger(frames) || frames < 1) throw new Error('video frame count is unavailable')
  return frames
}

async function validateBakeReceipt(path, ffprobe) {
  const { file, parsed: bake } = await readJsonFile(path, 'bake receipt')
  if (!isInside(TMP_ROOT, file.path)) throw new Error('bake receipt must be under tmp/')
  if (bake.schemaVersion !== 1 || bake.kind !== 'bitterclip.homepage.iso4.release-bake') {
    throw new Error('unsupported ISO4 bake receipt')
  }
  if (bake.mode !== 'complete' || bake.timeline?.complete !== true) {
    throw new Error('release packet requires a complete bake, not a proof bake')
  }
  const rendererInputs = validateRendererInputReceipt(bake.rendererInputs)
  if (bake.determinism?.pass !== true || bake.master?.terminalIdentity?.pass !== true) {
    throw new Error('bake receipt does not prove deterministic terminal identity')
  }
  if ((bake.homepage?.pageErrors?.length ?? 0) || (bake.homepage?.consoleErrors?.length ?? 0)) {
    throw new Error('bake receipt contains homepage or console errors')
  }
  const homepageUrl = new URL(bake.homepage?.url)
  if (homepageUrl.pathname !== '/') throw new Error('bake receipt is not canonical homepage evidence')
  const fps = Number(bake.timeline?.fps)
  if (fps !== 60) throw new Error(`bake frame rate is ${fps}, not 60fps`)
  const dpr = Number(bake.homepage?.dpr)
  if (!Number.isFinite(dpr) || dpr <= 0) throw new Error('bake homepage DPR is invalid')
  const expectedFrames = Number(bake.timeline?.renderedTotalFrameCount)
  if (!Number.isInteger(expectedFrames) || expectedFrames < 2) throw new Error('bake timeline frame count is invalid')
  if (expectedFrames !== Number(bake.timeline?.completeTotalFrameCount)) {
    throw new Error('complete bake rendered frame count is inconsistent')
  }
  const terminalFrame = Number(bake.timeline?.renderedTerminalFrameIndex)
  const terminalHoldFrames = Number(bake.timeline?.terminalHoldFrameCount)
  if (!Number.isInteger(terminalFrame) || !Number.isInteger(terminalHoldFrames)
    || terminalFrame < 1 || terminalHoldFrames < 1
    || terminalFrame + terminalHoldFrames !== expectedFrames) {
    throw new Error('bake terminal frame and hold do not fund the exact total duration')
  }
  if (Number(bake.master?.frameCount) !== expectedFrames || bake.master?.codec !== 'ffv1') {
    throw new Error('bake master accounting is inconsistent')
  }

  const master = await verifyReceiptFile(bake.master, 'bake master', { inside: TMP_ROOT })
  const masterProbe = await probe(master.path, ffprobe, { countFrames: true })
  const videos = masterProbe.streams.filter((stream) => stream.codec_type === 'video')
  const audios = masterProbe.streams.filter((stream) => stream.codec_type === 'audio')
  if (videos.length !== 1 || videos[0].codec_name !== 'ffv1' || audios.length) {
    throw new Error('bake master is not one silent FFV1 video stream')
  }
  if (Math.abs(fraction(videos[0].avg_frame_rate) - fps) > 1e-6 || countFrames(videos[0]) !== expectedFrames) {
    throw new Error('bake master probe does not match timeline accounting')
  }
  const dimensions = { width: Number(videos[0].width), height: Number(videos[0].height) }
  if (!(dimensions.width > 0 && dimensions.height > 0)
    || Number(bake.posters?.dimensions?.width) !== dimensions.width
    || Number(bake.posters?.dimensions?.height) !== dimensions.height) {
    throw new Error('bake master and poster dimensions do not match')
  }
  const opening = await verifyReceiptFile(bake.posters?.opening, 'bake opening poster', { inside: TMP_ROOT })
  const terminal = await verifyReceiptFile(bake.posters?.terminal, 'bake terminal poster', { inside: TMP_ROOT })
  const source = await verifyReceiptFile(bake.source, 'bake source', { inside: REPO_ROOT })
  return {
    file: { ...file, sha256: await sha256(file.path) },
    bake,
    master,
    source,
    rendererInputs,
    bakePosters: { opening, terminal },
    probe: masterProbe,
    fps,
    frameCount: expectedFrames,
    dpr,
    dimensions,
  }
}

async function validateEncodeReceipt(path, selection, bakeValidation, ffprobe) {
  const { file, parsed: encode } = await readJsonFile(path, 'encode receipt')
  if (!isInside(TMP_ROOT, file.path)) throw new Error('encode receipt must be under tmp/')
  if (encode.schema !== 'bitterclip.iso4-artifact-encode.v1') throw new Error('unsupported encode receipt')
  if (encode.contract?.codec !== 'h264' || Number(encode.contract?.fps) !== 60
    || encode.contract?.pixelFormat !== 'yuv420p' || encode.contract?.audio !== false
    || encode.contract?.fastStart !== true) {
    throw new Error('encode receipt contract is not the accepted H.264 delivery contract')
  }
  const encodedSource = await verifyReceiptFile(encode.source, 'encode source', { inside: TMP_ROOT })
  if (encodedSource.sha256 !== bakeValidation.master.sha256) {
    throw new Error('encode source does not match the verified bake master')
  }
  if (!Array.isArray(encode.candidates) || !encode.candidates.length) {
    throw new Error('encode receipt has no candidates')
  }
  const candidateCrfs = encode.candidates.map((entry) => Number(entry.crf))
  const candidatePaths = encode.candidates.map((entry) => resolve(entry.path))
  if (new Set(candidateCrfs).size !== candidateCrfs.length || new Set(candidatePaths).size !== candidatePaths.length) {
    throw new Error('encode receipt contains ambiguous duplicate candidates')
  }
  let matches
  if (selection.crf !== undefined) {
    const crf = Number(selection.crf)
    if (![15, 18, 21].includes(crf)) throw new Error('--crf must be 15, 18, or 21')
    matches = encode.candidates.filter((entry) => Number(entry.crf) === crf)
  } else {
    const candidatePath = resolve(selection.candidate)
    matches = encode.candidates.filter((entry) => resolve(entry.path) === candidatePath)
  }
  if (matches.length !== 1) throw new Error('selected candidate is not identified exactly once in the encode receipt')
  const [candidate] = matches
  const selected = await verifyReceiptFile(candidate, 'selected H.264 candidate', { inside: TMP_ROOT })
  const claimedChecks = Object.values(candidate.checks ?? {})
  if (claimedChecks.length < 6 || claimedChecks.some((value) => value !== true)) {
    throw new Error('selected candidate receipt contains a failed or incomplete delivery check')
  }
  if (candidate.ssim?.parsed !== true || !Number.isFinite(Number(candidate.ssim?.all))) {
    throw new Error('selected candidate receipt lacks a parsed SSIM measurement')
  }

  const actualProbe = await probe(selected.path, ffprobe, { countFrames: true })
  const videos = actualProbe.streams.filter((stream) => stream.codec_type === 'video')
  const audios = actualProbe.streams.filter((stream) => stream.codec_type === 'audio')
  if (videos.length !== 1 || audios.length) throw new Error('selected candidate must contain one video stream and no audio')
  const video = videos[0]
  const rate = fraction(video.avg_frame_rate || video.r_frame_rate)
  const failures = []
  if (video.codec_name !== 'h264') failures.push(`codec=${video.codec_name}`)
  const formatNames = String(actualProbe.format?.format_name || '').split(',')
  if (!formatNames.some((name) => name === 'mp4' || name === 'mov')) failures.push(`container=${actualProbe.format?.format_name}`)
  if (video.pix_fmt !== 'yuv420p') failures.push(`pixel_format=${video.pix_fmt}`)
  if (video.width !== bakeValidation.dimensions.width || video.height !== bakeValidation.dimensions.height) {
    failures.push(`dimensions=${video.width}x${video.height}`)
  }
  if (Math.abs(rate - 60) > 1e-6) failures.push(`frame_rate=${video.avg_frame_rate}`)
  if (video.color_range !== 'tv') failures.push(`color_range=${video.color_range}`)
  if (video.color_space !== 'bt709' || video.color_primaries !== 'bt709' || video.color_transfer !== 'bt709') {
    failures.push('color_metadata!=bt709')
  }
  const frameCount = countFrames(video)
  if (frameCount !== bakeValidation.frameCount) failures.push(`frames=${frameCount}`)
  const encodedDuration = Number(actualProbe.format?.duration)
  const frameDuration = frameCount / rate
  if (!Number.isFinite(encodedDuration) || Math.abs(encodedDuration - frameDuration) > (1 / rate) + 1e-6) {
    failures.push(`duration=${actualProbe.format?.duration}`)
  }
  const startup = await fastStart(selected.path)
  if (!startup.valid) failures.push('faststart=false')
  if (failures.length) throw new Error(`selected candidate probe failed: ${failures.join(', ')}`)
  return {
    file: { ...file, sha256: await sha256(file.path) },
    encode,
    candidate,
    selected,
    probe: actualProbe,
    video,
    frameCount,
    fps: rate,
    duration: encodedDuration,
    fastStart: startup,
  }
}

function sharedRendererContract(validation) {
  const { bake } = validation.bakeValidation
  const renderer = bake.homepage?.renderer ?? {}
  return canonicalValue({
    script_version: bake.scriptVersion,
    workshop: bake.homepage?.workshop,
    release_contract: bake.homepage?.releaseContract,
    environment: {
      node: bake.environment?.node,
      browser: bake.environment?.browserVersion,
      ffmpeg: bake.environment?.ffmpeg,
      ffprobe: bake.environment?.ffprobe,
    },
    webgl: {
      vendor: renderer.vendor,
      renderer: renderer.renderer,
      version: renderer.version,
      shading_language_version: renderer.shadingLanguageVersion,
    },
  })
}

function validateVariantSet(validations, mode) {
  if (!validations.length || validations.length > 8) throw new Error('variant validation requires 1-8 entries')
  const first = validations[0]
  const expected = {
    sourceSha256: first.bakeValidation.source.sha256,
    rendererInputsSha256: first.bakeValidation.rendererInputs.contentSha256,
    fps: first.encodeValidation.fps,
    frameCount: first.encodeValidation.frameCount,
    encodedDuration: first.encodeValidation.duration,
    renderedDuration: Number(first.bakeValidation.bake.timeline.renderedDurationSeconds),
    sceneTerminalTime: Number(first.bakeValidation.bake.timeline.sceneTerminalTime),
    sceneTerminalFrame: Number(first.bakeValidation.bake.timeline.sceneTerminalFrameIndex),
    terminalFrame: Number(first.bakeValidation.bake.timeline.renderedTerminalFrameIndex),
    terminalHoldFrames: Number(first.bakeValidation.bake.timeline.terminalHoldFrameCount),
    terminalHoldSeconds: Number(first.bakeValidation.bake.timeline.terminalHoldSeconds),
    repositoryHead: String(first.bakeValidation.bake.repository?.head ?? ''),
    repositoryBranch: String(first.bakeValidation.bake.repository?.branch ?? ''),
    rendererContract: canonicalJson(sharedRendererContract(first)),
  }
  if (mode === 'multi') {
    if (!/^[a-f0-9]{40}$/.test(expected.repositoryHead)) {
      throw new Error('multi-variant bake lacks one clean identified Git revision')
    }
    const bake = first.bakeValidation.bake
    if (typeof bake.scriptVersion !== 'string' || !bake.scriptVersion
      || !bake.homepage?.workshop || !bake.homepage?.releaseContract
      || typeof bake.environment?.browserVersion !== 'string') {
      throw new Error('multi-variant bake lacks an identified renderer contract')
    }
  }
  for (const validation of validations) {
    const { variant, bakeValidation, encodeValidation } = validation
    const bake = bakeValidation.bake
    if (bakeValidation.source.sha256 !== expected.sourceSha256) {
      throw new Error(`${variant.profile} bake source hash differs from the generation source`)
    }
    if (bakeValidation.rendererInputs.contentSha256 !== expected.rendererInputsSha256) {
      throw new Error(`${variant.profile} bake renderer inputs differ from the generation source`)
    }
    if (encodeValidation.fps !== 60 || encodeValidation.fps !== expected.fps) {
      throw new Error(`${variant.profile} does not share the exact 60fps contract`)
    }
    if (encodeValidation.frameCount !== expected.frameCount
      || encodeValidation.duration !== expected.encodedDuration
      || Number(bake.timeline.renderedTotalFrameCount) !== expected.frameCount
      || Number(bake.timeline.renderedDurationSeconds) !== expected.renderedDuration
      || Number(bake.timeline.completeDurationSeconds) !== expected.renderedDuration) {
      throw new Error(`${variant.profile} does not share the encoded duration/frame count`)
    }
    if (Number(bake.timeline.sceneTerminalTime) !== expected.sceneTerminalTime
      || Number(bake.timeline.sceneTerminalFrameIndex) !== expected.sceneTerminalFrame
      || Number(bake.timeline.renderedTerminalFrameIndex) !== expected.terminalFrame
      || Number(bake.timeline.terminalHoldFrameCount) !== expected.terminalHoldFrames
      || Number(bake.timeline.terminalHoldSeconds) !== expected.terminalHoldSeconds) {
      throw new Error(`${variant.profile} does not share terminal frame/hold accounting`)
    }
    if (canonicalJson(sharedRendererContract(validation)) !== expected.rendererContract) {
      throw new Error(`${variant.profile} does not share the renderer contract`)
    }
    if (mode === 'multi') {
      const repository = bake.repository ?? {}
      if (repository.head !== expected.repositoryHead || repository.branch !== expected.repositoryBranch) {
        throw new Error(`${variant.profile} was not baked from the same identified source revision`)
      }
    }
  }
  const duplicateChecks = [
    ['bake receipts', validations.map((entry) => entry.bakeValidation.file.path)],
    ['encode receipts', validations.map((entry) => entry.encodeValidation.file.path)],
    ['selected H.264 paths', validations.map((entry) => entry.encodeValidation.selected.path)],
    ['selected H.264 assets', validations.map((entry) => entry.encodeValidation.selected.sha256)],
  ]
  for (const [label, values] of duplicateChecks) {
    if (new Set(values).size !== values.length) throw new Error(`variant spec contains duplicate ${label}`)
  }
  return expected
}

const SENSITIVE_PATH = /(?:^|\/)(?:\.env(?:\.|$)|id_(?:rsa|dsa|ecdsa|ed25519)(?:\.|$)|credentials?(?:\.|$)|secrets?(?:\.|$))|\.(?:pem|key|p12|pfx|jks|keystore)$/i
const FORBIDDEN_SOURCE_ROOT = /^(?:\.git|tmp|node_modules|\.nuxt|\.output|dist)(?:\/|$)/

async function declaredBundleFiles(options, bakeSourcePaths) {
  const groups = [
    ['source', options.sourceFiles],
    ['media', options.mediaFiles],
    ['dependency', options.dependencyFiles],
  ]
  for (const [role, values] of groups) {
    if (!values.length) throw new Error(`at least one --${role}-file declaration is required`)
  }
  const seen = new Set()
  const files = []
  let totalBytes = 0
  for (const [role, values] of groups) {
    for (const rawPath of values) {
      const file = await exactRegularFile(resolve(REPO_ROOT, rawPath), { inside: REPO_ROOT })
      const repositoryPath = relative(REPO_ROOT, file.path).split(sep).join('/')
      if (!repositoryPath || repositoryPath.startsWith('../') || FORBIDDEN_SOURCE_ROOT.test(repositoryPath)) {
        throw new Error(`bundle input is outside the durable source boundary: ${repositoryPath}`)
      }
      if (SENSITIVE_PATH.test(repositoryPath)) throw new Error(`refusing sensitive-looking bundle input: ${repositoryPath}`)
      if (seen.has(repositoryPath)) throw new Error(`bundle input is declared more than once: ${repositoryPath}`)
      seen.add(repositoryPath)
      totalBytes += file.bytes
      if (totalBytes > MAX_BUNDLE_INPUT_BYTES) throw new Error('declared source bundle exceeds the 1 GiB input budget')
      files.push({
        role,
        path: file.path,
        repositoryPath,
        bytes: file.bytes,
        sha256: await sha256(file.path),
      })
    }
  }
  for (const bakeSourcePath of new Set(bakeSourcePaths)) {
    const bakedSource = relative(REPO_ROOT, bakeSourcePath).split(sep).join('/')
    const bakedSourceEntry = files.find((entry) => entry.repositoryPath === bakedSource)
    if (!bakedSourceEntry || bakedSourceEntry.role !== 'media') {
      throw new Error(`--media-file declarations must include the exact baked source: ${bakedSource}`)
    }
  }
  const ordered = files.sort((a, b) => a.repositoryPath.localeCompare(b.repositoryPath))
  // This rejects both omissions and seemingly harmless extras. Without an
  // exact set, an operator could omit a dirty scene input or make generation
  // identity depend on unrelated repository content.
  rendererInputReceiptFromEntries(ordered)
  return ordered
}

function verifyBakesMatchBundledRendererInputs(validations, bundleFiles) {
  const bundled = rendererInputReceiptFromEntries(bundleFiles)
  const bundledByPath = new Map(bundleFiles.map((file) => [file.repositoryPath, file]))
  for (const validation of validations) {
    const baked = validation.bakeValidation.rendererInputs
    if (baked.contentSha256 !== bundled.contentSha256) {
      throw new Error(
        `${validation.variant.profile} bake renderer-input hash does not match the bundled bytes`,
      )
    }
    for (const receipt of baked.files) {
      const bundledFile = bundledByPath.get(receipt.path)
      if (!bundledFile
        || bundledFile.role !== receipt.role
        || bundledFile.bytes !== receipt.byte_size
        || bundledFile.sha256 !== receipt.sha256) {
        throw new Error(
          `${validation.variant.profile} bake renderer-input receipt does not match bundled bytes: ${receipt.path}`,
        )
      }
    }
  }
  return bundled
}

async function verifyCurrentCleanRevision(shared, files, mode) {
  if (mode !== 'multi') return
  const [{ stdout: head }, { stdout: branch }] = await Promise.all([
    run('git', ['rev-parse', 'HEAD']),
    run('git', ['branch', '--show-current']),
  ])
  if (head.trim() !== shared.repositoryHead || branch.trim() !== shared.repositoryBranch) {
    throw new Error('current checkout does not match the source revision identified by every bake')
  }
  const repositoryPaths = files.map((file) => file.repositoryPath)
  const { stdout: status } = await run('git', [
    'status', '--porcelain=v1', '--untracked-files=all', '--', ...repositoryPaths,
  ])
  if (status.trim()) {
    throw new Error(`declared source bundle inputs differ from the identified bake revision:\n${status.trim()}`)
  }
  const tracked = await run('git', ['ls-files', '--error-unmatch', '--', ...repositoryPaths])
  const trackedPaths = new Set(tracked.stdout.trim().split('\n').filter(Boolean))
  const missing = repositoryPaths.filter((path) => !trackedPaths.has(path))
  if (missing.length) throw new Error(`declared source inputs are not tracked at the identified bake revision: ${missing.join(', ')}`)
}

function canonicalValue(value) {
  if (Array.isArray(value)) return value.map(canonicalValue)
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, canonicalValue(value[key])]))
  }
  return value
}

function canonicalJson(value) {
  return JSON.stringify(canonicalValue(value))
}

function tarPathFields(path) {
  const bytes = Buffer.byteLength(path)
  if (bytes <= 100) return { name: path, prefix: '' }
  const parts = path.split('/')
  for (let split = 1; split < parts.length; split++) {
    const prefix = parts.slice(0, split).join('/')
    const name = parts.slice(split).join('/')
    if (Buffer.byteLength(prefix) <= 155 && Buffer.byteLength(name) <= 100) return { name, prefix }
  }
  throw new Error(`bundle path is too long for deterministic ustar: ${path}`)
}

function writeString(header, offset, length, value) {
  const bytes = Buffer.from(value, 'utf8')
  if (bytes.length > length) throw new Error(`ustar field is too long: ${value}`)
  bytes.copy(header, offset)
}

function writeOctal(header, offset, length, value) {
  const digits = Math.trunc(value).toString(8)
  if (digits.length > length - 1) throw new Error(`ustar numeric field overflow: ${value}`)
  writeString(header, offset, length, `${digits.padStart(length - 1, '0')}\0`)
}

function tarHeader(path, size) {
  const header = Buffer.alloc(512)
  const { name, prefix } = tarPathFields(path)
  writeString(header, 0, 100, name)
  writeOctal(header, 100, 8, 0o644)
  writeOctal(header, 108, 8, 0)
  writeOctal(header, 116, 8, 0)
  writeOctal(header, 124, 12, size)
  writeOctal(header, 136, 12, 0)
  header.fill(0x20, 148, 156)
  writeString(header, 156, 1, '0')
  writeString(header, 257, 6, 'ustar\0')
  writeString(header, 263, 2, '00')
  writeString(header, 345, 155, prefix)
  const checksum = header.reduce((sum, byte) => sum + byte, 0)
  writeString(header, 148, 8, `${checksum.toString(8).padStart(6, '0')}\0 `)
  return header
}

function buildTar(entries) {
  const buffers = []
  for (const entry of entries) {
    buffers.push(tarHeader(entry.path, entry.bytes.length), entry.bytes)
    const padding = (512 - (entry.bytes.length % 512)) % 512
    if (padding) buffers.push(Buffer.alloc(padding))
  }
  buffers.push(Buffer.alloc(1024))
  return Buffer.concat(buffers)
}

async function buildSourceBundle(files, stagingBundleDir, finalBundleDir) {
  const sourceManifest = {
    schema: SOURCE_BUNDLE_SCHEMA,
    files: files.map((entry) => ({
      path: entry.repositoryPath,
      role: entry.role,
      byte_size: entry.bytes,
      sha256: entry.sha256,
    })),
  }
  const entries = [{
    path: 'bundle-manifest.json',
    bytes: Buffer.from(`${canonicalJson(sourceManifest)}\n`),
  }]
  for (const file of files) {
    const bytes = await readFile(file.path)
    if (bytes.length !== file.bytes || sha256Buffer(bytes) !== file.sha256) {
      throw new Error(`bundle input changed after provenance validation: ${file.repositoryPath}`)
    }
    entries.push({
      path: `repository/${file.repositoryPath}`,
      bytes,
    })
  }
  entries.sort((a, b) => a.path.localeCompare(b.path))
  const tar = buildTar(entries)
  const first = gzipSync(tar, { level: 9, mtime: 0 })
  const second = gzipSync(buildTar(entries), { level: 9, mtime: 0 })
  if (first[0] !== 0x1f || first[1] !== 0x8b) throw new Error('source bundle lacks gzip magic')
  if (!first.equals(second) || !gunzipSync(first).equals(tar)) {
    throw new Error('source bundle did not pass deterministic gzip round-trip verification')
  }
  const digest = sha256Buffer(first)
  const filename = `source-bundle-${digest}.tgz`
  const stagingPath = resolve(stagingBundleDir, filename)
  const finalPath = resolve(finalBundleDir, filename)
  await mkdir(stagingBundleDir, { recursive: true })
  await writeFile(stagingPath, first, { flag: 'wx' })
  if (await sha256(stagingPath) !== digest) throw new Error('written source bundle hash changed')
  return {
    path: finalPath,
    stagingPath,
    bytes: first.length,
    sha256: digest,
    tarSha256: sha256Buffer(tar),
    deterministicReplaySha256: sha256Buffer(second),
    manifest: sourceManifest,
  }
}

async function decodeFrame(videoPath, frameIndex, outputPath, ffmpeg) {
  await mkdir(dirname(outputPath), { recursive: true })
  await run(ffmpeg, [
    '-hide_banner',
    '-loglevel', 'error',
    '-i', videoPath,
    '-map', '0:v:0',
    '-vf', `select=eq(n\\,${frameIndex})`,
    '-fps_mode', 'vfr',
    '-frames:v', '1',
    '-c:v', 'png',
    '-pred', 'mixed',
    '-n',
    outputPath,
  ])
  return await exactRegularFile(outputPath)
}

async function rgbaFingerprint(path, width, height, ffmpeg) {
  const { stdout } = await run(ffmpeg, [
    '-hide_banner',
    '-loglevel', 'error',
    '-i', path,
    '-map', '0:v:0',
    '-frames:v', '1',
    '-f', 'rawvideo',
    '-pix_fmt', 'rgba',
    '-',
  ], { binary: true })
  const expected = width * height * 4
  if (stdout.length !== expected) throw new Error(`decoded RGBA byte count ${stdout.length} does not match ${expected}: ${path}`)
  return { bytes: stdout.length, sha256: sha256Buffer(stdout) }
}

function parseQualityMetric(stderr, name) {
  if (name === 'ssim') {
    const match = stderr.match(/All:([^ ]+)/)
    return match ? Number(match[1]) : null
  }
  const match = stderr.match(/average:([^ ]+)/)
  if (!match) return null
  return match[1] === 'inf' ? 'inf' : Number(match[1])
}

async function posterMetrics(referencePath, posterPath, ffmpeg) {
  const ssim = await run(ffmpeg, [
    '-hide_banner', '-loglevel', 'info',
    '-i', posterPath,
    '-i', referencePath,
    '-filter_complex', '[0:v]format=gbrp[dist];[1:v]format=gbrp[ref];[dist][ref]ssim',
    '-f', 'null', '-',
  ])
  const psnr = await run(ffmpeg, [
    '-hide_banner', '-loglevel', 'info',
    '-i', posterPath,
    '-i', referencePath,
    '-filter_complex', '[0:v]format=gbrp[dist];[1:v]format=gbrp[ref];[dist][ref]psnr',
    '-f', 'null', '-',
  ])
  const ssimAll = parseQualityMetric(ssim.stderr, 'ssim')
  const psnrAverage = parseQualityMetric(psnr.stderr, 'psnr')
  if (ssimAll === null || psnrAverage === null) throw new Error(`poster metrics did not parse: ${posterPath}`)
  return { ssimAll, psnrAverage }
}

async function imageReceipt(path, width, height, ffprobe, ffmpeg, referencePath = null) {
  const file = await exactRegularFile(path)
  const imageProbe = await probe(file.path, ffprobe)
  const videos = imageProbe.streams.filter((stream) => stream.codec_type === 'video')
  if (videos.length !== 1 || videos[0].codec_name !== 'webp'
    || videos[0].width !== width || videos[0].height !== height) {
    throw new Error(`poster probe is not the expected ${width}x${height} WebP: ${path}`)
  }
  const rgba = await rgbaFingerprint(file.path, width, height, ffmpeg)
  return {
    path: file.path,
    bytes: file.bytes,
    sha256: await sha256(file.path),
    probe: imageProbe,
    rgba,
    metrics: referencePath ? await posterMetrics(referencePath, file.path, ffmpeg) : null,
  }
}

async function encodePosterCandidates(referencePath, stem, dimensions, stagingDir, finalDir, tools) {
  const stagingReference = resolve(stagingDir, `${stem}-reference.ppm`)
  const stagingLossless = resolve(stagingDir, `${stem}-lossless.webp`)
  const stagingQ92 = resolve(stagingDir, `${stem}-q92-sharp-yuv.webp`)
  await mkdir(stagingDir, { recursive: true })
  // FFmpeg tags decoded BT.709 PNGs with a gAMA chunk. cwebp color-manages
  // that metadata while WebP itself carries no equivalent tag, which makes a
  // nominally lossless poster visibly darker on decode. PPM preserves the
  // selected H.264 frame's exact RGB samples without ambient color metadata.
  await run(tools.ffmpeg, [
    '-hide_banner', '-loglevel', 'error', '-y',
    '-i', referencePath,
    '-map', '0:v:0',
    '-frames:v', '1',
    '-pix_fmt', 'rgb24',
    stagingReference,
  ])
  const ppmFile = await exactRegularFile(stagingReference)
  const ppmSha256 = await sha256(stagingReference)
  await run(tools.cwebp, [
    '-quiet', '-lossless', '-exact', '-m', '6', '-metadata', 'none',
    stagingReference, '-o', stagingLossless,
  ])
  await run(tools.cwebp, [
    '-quiet', '-q', '92', '-m', '6', '-sharp_yuv', '-metadata', 'none',
    stagingReference, '-o', stagingQ92,
  ])
  const [lossless, q92] = await Promise.all([
    imageReceipt(stagingLossless, dimensions.width, dimensions.height, tools.ffprobe, tools.ffmpeg, referencePath),
    imageReceipt(stagingQ92, dimensions.width, dimensions.height, tools.ffprobe, tools.ffmpeg, referencePath),
  ])
  const referenceRgba = await rgbaFingerprint(referencePath, dimensions.width, dimensions.height, tools.ffmpeg)
  if (lossless.rgba.sha256 !== referenceRgba.sha256 || lossless.metrics.ssimAll !== 1) {
    throw new Error(`${stem} lossless WebP does not decode identically to the selected H.264 frame`)
  }
  await rm(stagingReference)
  const finalize = (receipt, filename) => ({
    ...receipt,
    path: resolve(finalDir, filename),
    stagingPath: receipt.path,
  })
  return {
    ingest: {
      format: 'ppm',
      metadata: false,
      bytes: ppmFile.bytes,
      sha256: ppmSha256,
    },
    reference: {
      path: referencePath,
      bytes: (await stat(referencePath)).size,
      sha256: await sha256(referencePath),
      rgba: referenceRgba,
    },
    lossless: finalize(lossless, basename(stagingLossless)),
    q92: finalize(q92, basename(stagingQ92)),
  }
}

function normalizedComponent(value, label) {
  const text = String(value ?? '')
  if (!COMPONENT_PATTERN.test(text)) throw new Error(`${label} is invalid for the BitterClip manifest contract`)
  return text
}

function definitionFingerprint(manifest) {
  return sha256Buffer(Buffer.from(canonicalJson(manifest)))
}

function releaseAsset({ name, role, profile, path, receipt, access, width, height, frameRate, codec }) {
  const asset = {
    name,
    role,
    profile,
    content_type: role === 'video' ? 'video/mp4'
      : role === 'source_bundle' ? 'application/gzip'
        : 'image/webp',
    sha256: receipt.sha256,
    byte_size: receipt.bytes,
    access,
  }
  if (width) asset.width = width
  if (height) asset.height = height
  if (frameRate) asset.frame_rate = frameRate
  if (codec) asset.codec = codec
  return { asset, path }
}

function validateCli(options) {
  const required = ['accountPublicId', 'output']
  for (const key of required) if (!options[key]) throw new Error(`--${key.replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`)} is required\n\n${usage}`)
  if (options.variantSpec) {
    const incompatible = ['bakeReceipt', 'encodeReceipt', 'crf', 'candidate', 'profile', 'mediaQuery']
      .filter((key) => options.provided.has(key))
    if (incompatible.length) {
      throw new Error(`--variant-spec cannot be combined with single-profile options: ${incompatible.join(', ')}`)
    }
  } else {
    if (!options.bakeReceipt || !options.encodeReceipt) {
      throw new Error('--bake-receipt and --encode-receipt are required without --variant-spec')
    }
    if ((options.crf === undefined) === (options.candidate === undefined)) {
      throw new Error('exactly one of --crf or --candidate is required')
    }
  }
  if (!ACCOUNT_PATTERN.test(options.accountPublicId)) throw new Error('--account-public-id is invalid')
  if (!NAME_PATTERN.test(options.profile) || options.profile.length > MAX_VARIANT_PROFILE_CHARS) {
    throw new Error('--profile is invalid or too long for derived asset names')
  }
  if (!NAME_PATTERN.test(options.definitionKey)) throw new Error('--definition-key is invalid')
  if (!['q92', 'lossless'].includes(options.posterProfile)) {
    throw new Error('--poster-profile must be q92 or lossless')
  }
  if (!String(options.definitionName).trim() || Buffer.byteLength(options.definitionName) > 160) {
    throw new Error('--definition-name must contain 1-160 bytes')
  }
  if (options.expectedAcceptanceVersion !== undefined) {
    const version = Number(options.expectedAcceptanceVersion)
    if (!Number.isInteger(version) || version < 0) throw new Error('--expected-acceptance-version must be a nonnegative integer')
    options.expectedAcceptanceVersion = version
  }
  const output = resolve(options.output)
  if (!isInside(TMP_ROOT, output) || output === TMP_ROOT) {
    throw new Error(`--output must be a dedicated directory under ${TMP_ROOT}`)
  }
  options.output = output
  return options
}

async function toolVersion(command, mode) {
  const args = mode === 'cwebp' ? ['-version'] : ['-version']
  const result = await run(command, args)
  return `${result.stdout}\n${result.stderr}`.trim().split('\n')[0]
}

async function validateVariants(inputs, tools) {
  const validations = []
  for (const variant of inputs.variants) {
    const bakeValidation = await validateBakeReceipt(variant.bakeReceipt, tools.ffprobe)
    const encodeValidation = await validateEncodeReceipt(
      variant.encodeReceipt,
      variant.selection,
      bakeValidation,
      tools.ffprobe,
    )
    const dimensions = {
      width: Number(encodeValidation.video.width),
      height: Number(encodeValidation.video.height),
    }
    if (!Number.isInteger(dimensions.width) || !Number.isInteger(dimensions.height)
      || dimensions.width < 1 || dimensions.height < 1
      || dimensions.width > 8192 || dimensions.height > 8192) {
      throw new Error(`${variant.profile} dimensions exceed the BitterClip visual asset contract`)
    }
    const profileContract = PROFILE_CONTRACTS[variant.profile]
    if (profileContract && (profileContract.width !== dimensions.width || profileContract.height !== dimensions.height)) {
      throw new Error(`${variant.profile} profile requires ${profileContract.width}x${profileContract.height}; candidate is ${dimensions.width}x${dimensions.height}`)
    }
    validations.push({ variant, bakeValidation, encodeValidation, dimensions })
  }
  const shared = validateVariantSet(validations, inputs.mode)
  return { validations, shared }
}

async function prepareVariantMaterial(validation, inputs, options, staging, tools) {
  const { variant, bakeValidation, encodeValidation, dimensions } = validation
  const variantDirectory = inputs.mode === 'single' ? '' : variant.profile
  const decodedStaging = resolve(staging, 'decoded', variantDirectory)
  const openingPng = resolve(decodedStaging, 'opening-from-selected-h264.png')
  const terminalPng = resolve(decodedStaging, 'terminal-from-selected-h264.png')
  await decodeFrame(encodeValidation.selected.path, 0, openingPng, tools.ffmpeg)
  await decodeFrame(encodeValidation.selected.path, encodeValidation.frameCount - 1, terminalPng, tools.ffmpeg)
  const decodedOpeningProbe = await probe(openingPng, tools.ffprobe)
  const decodedTerminalProbe = await probe(terminalPng, tools.ffprobe)
  for (const [label, imageProbe] of [['opening', decodedOpeningProbe], ['terminal', decodedTerminalProbe]]) {
    const stream = imageProbe.streams.find((entry) => entry.codec_type === 'video')
    if (!stream || stream.codec_name !== 'png' || stream.width !== dimensions.width || stream.height !== dimensions.height) {
      throw new Error(`${variant.profile} ${label} selected-frame decode is not ${dimensions.width}x${dimensions.height} PNG`)
    }
  }

  const assetVariantDirectory = inputs.mode === 'single' ? variant.profile : variantDirectory
  const stagingAssetDirectory = resolve(staging, 'assets', assetVariantDirectory)
  const finalAssetDirectory = resolve(options.output, 'assets', assetVariantDirectory)
  await mkdir(stagingAssetDirectory, { recursive: true })
  const videoFilename = `${variant.profile}-h264-${encodeValidation.selected.sha256}.mp4`
  const stagingVideoPath = resolve(stagingAssetDirectory, videoFilename)
  const finalVideoPath = resolve(finalAssetDirectory, videoFilename)
  await copyFile(encodeValidation.selected.path, stagingVideoPath, fsConstants.COPYFILE_EXCL)
  const frozenVideo = await exactRegularFile(stagingVideoPath)
  frozenVideo.sha256 = await sha256(stagingVideoPath)
  if (frozenVideo.bytes !== encodeValidation.selected.bytes
    || frozenVideo.sha256 !== encodeValidation.selected.sha256) {
    throw new Error(`${variant.profile} frozen delivery video differs from the selected candidate`)
  }

  const posterStaging = resolve(stagingAssetDirectory, 'posters')
  const posterFinal = resolve(finalAssetDirectory, 'posters')
  const [openingPosters, terminalPosters] = await Promise.all([
    encodePosterCandidates(openingPng, 'opening', dimensions, posterStaging, posterFinal, tools),
    encodePosterCandidates(terminalPng, 'terminal', dimensions, posterStaging, posterFinal, tools),
  ])
  const selectedOpening = openingPosters[options.posterProfile]
  const selectedTerminal = terminalPosters[options.posterProfile]
  if (!selectedOpening || !selectedTerminal) throw new Error(`${variant.profile} selected poster profile was not generated`)
  for (const beat of [openingPosters, terminalPosters]) {
    for (const key of ['lossless', 'q92']) delete beat[key].stagingPath
    beat.reference.path = resolve(options.output, 'decoded', variantDirectory, basename(beat.reference.path))
  }

  const entries = [
    releaseAsset({
      name: `${variant.profile}-h264`,
      role: 'video',
      profile: variant.profile,
      path: finalVideoPath,
      receipt: frozenVideo,
      access: 'public',
      ...dimensions,
      frameRate: '60/1',
      codec: 'h264',
    }),
    releaseAsset({
      name: `${variant.profile}-opening`,
      role: 'opening_poster',
      profile: variant.profile,
      path: selectedOpening.path,
      receipt: selectedOpening,
      access: 'public',
      ...dimensions,
    }),
    releaseAsset({
      name: `${variant.profile}-terminal`,
      role: 'terminal_poster',
      profile: variant.profile,
      path: selectedTerminal.path,
      receipt: selectedTerminal,
      access: 'public',
      ...dimensions,
    }),
  ]
  return {
    ...validation,
    entries,
    frozenVideo: { ...frozenVideo, path: finalVideoPath, stagingPath: stagingVideoPath },
    selectedOpening,
    selectedTerminal,
    posterReceipt: {
      profile: variant.profile,
      source_video: {
        sha256: encodeValidation.selected.sha256,
        frame_count: encodeValidation.frameCount,
      },
      opening: openingPosters,
      terminal: terminalPosters,
    },
    marketingVariant: {
      key: variant.profile,
      media: variant.mediaQuery,
      width: dimensions.width,
      height: dimensions.height,
      mp4Url: '',
      mp4Sha256: encodeValidation.selected.sha256,
      mp4Bytes: encodeValidation.selected.bytes,
      openingPosterUrl: '',
      openingPosterSha256: selectedOpening.sha256,
      terminalPosterUrl: '',
      terminalPosterSha256: selectedTerminal.sha256,
    },
    renderVariant: {
      profile: variant.profile,
      media_query: variant.mediaQuery,
      width: dimensions.width,
      height: dimensions.height,
      dpr: bakeValidation.dpr,
      h264_crf: Number(encodeValidation.candidate.crf),
    },
  }
}

async function main(rawOptions) {
  const options = validateCli(rawOptions)
  if (await exists(options.output)) throw new Error(`refusing to overwrite existing output: ${options.output}`)
  const staging = `${options.output}.staging-${process.pid}`
  if (await exists(staging)) throw new Error(`staging directory already exists: ${staging}`)
  await mkdir(staging, { recursive: true })

  try {
    const tools = { ffmpeg: options.ffmpeg, ffprobe: options.ffprobe, cwebp: options.cwebp }
    const toolVersions = {
      ffmpeg: await toolVersion(tools.ffmpeg, 'ffmpeg'),
      ffprobe: await toolVersion(tools.ffprobe, 'ffprobe'),
      cwebp: await toolVersion(tools.cwebp, 'cwebp'),
    }
    const inputs = await loadVariantInputs(options)
    const { validations, shared } = await validateVariants(inputs, tools)
    const bundleFiles = await declaredBundleFiles(
      options,
      validations.map((entry) => entry.bakeValidation.source.path),
    )
    const rendererInputs = verifyBakesMatchBundledRendererInputs(validations, bundleFiles)
    await verifyCurrentCleanRevision(shared, bundleFiles, inputs.mode)
    const finalBundleDir = resolve(options.output, 'assets/source')
    const sourceBundle = await buildSourceBundle(bundleFiles, resolve(staging, 'assets/source'), finalBundleDir)
    const prepared = []
    for (const validation of validations) {
      prepared.push(await prepareVariantMaterial(validation, inputs, options, staging, tools))
    }
    const fps = 60
    const durationMs = Math.round(shared.frameCount / fps * 1000)
    if (!Number.isInteger(durationMs) || durationMs < 1 || durationMs > 600_000) {
      throw new Error('responsive generation duration exceeds the BitterClip manifest contract')
    }
    const terminalFrame = shared.terminalFrame
    const terminalStateMs = Math.round(shared.sceneTerminalTime * 1000)
    if (!Number.isInteger(terminalFrame) || terminalFrame < 1 || terminalFrame >= shared.frameCount) {
      throw new Error('bake terminal frame is outside selected delivery video')
    }
    const identifiedRevision = inputs.mode === 'multi' ? `marketing.${shared.repositoryHead}` : null
    if (inputs.mode === 'multi' && options.sourceRevision
      && !String(options.sourceRevision).includes(shared.repositoryHead)) {
      throw new Error('--source-revision must include the complete clean bake Git revision in multi-variant mode')
    }
    const firstBake = prepared[0].bakeValidation.bake
    const auditRevision = options.sourceRevision || identifiedRevision || [
      'marketing',
      String(firstBake.repository?.head || '').slice(0, 12),
      sourceBundle.sha256.slice(0, 12),
    ].filter(Boolean).join('.')
    const cinematicRevision = `marketing.iso4.${rendererInputs.contentSha256}`
    const rendererVersion = options.rendererVersion
      || String(firstBake.scriptVersion || 'iso4-artifact-bake.v1').replaceAll('/', '.')

    const entries = [
      ...prepared.flatMap((entry) => entry.entries),
      releaseAsset({
        name: 'source-bundle',
        role: 'source_bundle',
        profile: 'source',
        path: sourceBundle.path,
        receipt: sourceBundle,
        access: 'private',
      }),
    ]
    const finalAssetRoot = resolve(options.output, 'assets')
    for (const entry of entries) {
      if (!isInside(finalAssetRoot, entry.path) || entry.path === finalAssetRoot) {
        throw new Error(`release asset is outside the generated ASSET_ROOT: ${entry.asset.name}`)
      }
    }
    const assetNames = entries.map((entry) => entry.asset.name)
    const assetPaths = entries.map((entry) => entry.path)
    const publicHashes = entries.filter((entry) => entry.asset.access === 'public').map((entry) => entry.asset.sha256)
    if (entries.length > 32) throw new Error('responsive generation exceeds BitterClip 32-asset manifest limit')
    if (entries.reduce((sum, entry) => sum + entry.asset.byte_size, 0) > 10 * 1024 * 1024 * 1024) {
      throw new Error('responsive generation exceeds BitterClip 10 GiB manifest limit')
    }
    if (new Set(assetNames).size !== assetNames.length) throw new Error('responsive generation contains duplicate asset names')
    if (new Set(assetPaths).size !== assetPaths.length) throw new Error('responsive generation contains duplicate asset paths')
    if (new Set(publicHashes).size !== publicHashes.length) throw new Error('responsive generation contains duplicate public asset bytes')

    const renderContract = {
      fps,
      non_looping: true,
      terminal_state_ms: terminalStateMs,
      terminal_frame: terminalFrame,
      terminal_hold_frames: shared.terminalHoldFrames,
      frame_count: shared.frameCount,
      pixel_format: 'yuv420p',
      color_space: 'bt709',
      color_range: 'limited',
      poster_origin: 'selected_h264_decode',
      poster_profile: options.posterProfile,
      input_media_sha256: shared.sourceSha256,
      renderer_inputs_sha256: rendererInputs.contentSha256,
      renderer_contract_sha256: sha256Buffer(Buffer.from(shared.rendererContract)),
    }
    if (inputs.mode === 'single') {
      renderContract.h264_crf = prepared[0].renderVariant.h264_crf
      renderContract.profile = prepared[0].variant.profile
      renderContract.viewport = {
        width: prepared[0].dimensions.width,
        height: prepared[0].dimensions.height,
        dpr: prepared[0].bakeValidation.dpr,
      }
    } else {
      renderContract.variants = prepared.map((entry) => entry.renderVariant)
    }
    const generation = {
      schema: GENERATION_SCHEMA,
      source: {
        sha256: sourceBundle.sha256,
        revision: normalizedComponent(cinematicRevision, 'source revision'),
      },
      renderer: {
        key: normalizedComponent(options.rendererKey, 'renderer key'),
        version: normalizedComponent(rendererVersion, 'renderer version'),
      },
      duration_ms: durationMs,
      render_contract: renderContract,
      assets: entries.map((entry) => entry.asset).sort((a, b) => a.name.localeCompare(b.name)),
    }
    const generationFingerprint = definitionFingerprint(generation)
    const packet = {
      schema: RELEASE_SCHEMA,
      account_public_id: options.accountPublicId,
      definition: {
        definition_key: options.definitionKey,
        name: String(options.definitionName).trim(),
        description: String(options.definitionDescription).trim(),
      },
      generation,
      asset_paths: Object.fromEntries(entries.map((entry) => [entry.asset.name, entry.path]).sort(([a], [b]) => a.localeCompare(b))),
    }
    if (options.expectedAcceptanceVersion !== undefined) {
      packet.accept = { expected_acceptance_version: options.expectedAcceptanceVersion }
    }
    const packetText = `${JSON.stringify(packet, null, 2)}\n`
    if (Buffer.byteLength(packetText) > MAX_PACKET_BYTES) throw new Error('release packet exceeds BitterClip 1 MiB packet budget')
    if (SECRET_TEXT_PATTERN.test(packetText)) {
      throw new Error('release packet contains secret-looking material')
    }

    const marketingManifest = {
      schema: MARKETING_SCHEMA,
      artifactId: 'homepage-iso4',
      generation: null,
      definitionFingerprint: generationFingerprint,
      sceneDurationMs: terminalStateMs,
      durationMs,
      fps,
      frameCount: shared.frameCount,
      terminalFrame,
      variants: prepared.map((entry) => entry.marketingVariant),
    }

    const packetDir = resolve(staging, 'packet')
    await mkdir(packetDir, { recursive: true })
    const generationPath = resolve(packetDir, 'generation-manifest.json')
    const packetPath = resolve(packetDir, 'release-packet.json')
    const marketingPath = resolve(packetDir, 'marketing-manifest-candidate.json')
    const posterReceiptPath = resolve(packetDir, 'poster-receipt.json')
    const bundleReceiptPath = resolve(packetDir, 'source-bundle-receipt.json')
    const finalPacketDir = resolve(options.output, 'packet')
    const posterReceipt = inputs.mode === 'single'
      ? {
          schema: 'bitterclip.iso4-poster-candidates.v1',
          selected_profile: options.posterProfile,
          source_video: prepared[0].posterReceipt.source_video,
          opening: prepared[0].posterReceipt.opening,
          terminal: prepared[0].posterReceipt.terminal,
        }
      : {
          schema: 'bitterclip.iso4-responsive-poster-candidates.v1',
          selected_profile: options.posterProfile,
          variants: prepared.map((entry) => entry.posterReceipt),
        }
    const bundleReceipt = {
      schema: 'bitterclip.iso4-source-bundle-receipt.v1',
      path: sourceBundle.path,
      bytes: sourceBundle.bytes,
      sha256: sourceBundle.sha256,
      tar_sha256: sourceBundle.tarSha256,
      deterministic_replay_sha256: sourceBundle.deterministicReplaySha256,
      deterministic: sourceBundle.sha256 === sourceBundle.deterministicReplaySha256,
      renderer_inputs_sha256: rendererInputs.contentSha256,
      manifest: sourceBundle.manifest,
    }
    if (!bundleReceipt.deterministic) throw new Error('source bundle deterministic receipt failed')

    await Promise.all([
      writeFile(generationPath, `${JSON.stringify(generation, null, 2)}\n`, { flag: 'wx' }),
      writeFile(packetPath, packetText, { flag: 'wx' }),
      writeFile(marketingPath, `${JSON.stringify(marketingManifest, null, 2)}\n`, { flag: 'wx' }),
      writeFile(posterReceiptPath, `${JSON.stringify(posterReceipt, null, 2)}\n`, { flag: 'wx' }),
      writeFile(bundleReceiptPath, `${JSON.stringify(bundleReceipt, null, 2)}\n`, { flag: 'wx' }),
    ])

    // Re-read the exact release packet before exposing it. This catches an
    // accidental serialization or local write failure independently of the
    // in-memory object.
    const persistedPacket = JSON.parse(await readFile(packetPath, 'utf8'))
    if (canonicalJson(persistedPacket) !== canonicalJson(packet)) throw new Error('persisted release packet changed during serialization')

    const packetInputs = inputs.mode === 'single'
      ? {
          bake_receipt: { path: prepared[0].bakeValidation.file.path, sha256: prepared[0].bakeValidation.file.sha256 },
          encode_receipt: { path: prepared[0].encodeValidation.file.path, sha256: prepared[0].encodeValidation.file.sha256 },
          selected_h264: {
            path: prepared[0].encodeValidation.selected.path,
            bytes: prepared[0].encodeValidation.selected.bytes,
            sha256: prepared[0].encodeValidation.selected.sha256,
            crf: Number(prepared[0].encodeValidation.candidate.crf),
            frame_count: prepared[0].encodeValidation.frameCount,
            fast_start: prepared[0].encodeValidation.fastStart,
          },
        }
      : {
          variant_spec: inputs.spec,
          variants: prepared.map((entry) => ({
            profile: entry.variant.profile,
            media_query: entry.variant.mediaQuery,
            bake_receipt: { path: entry.bakeValidation.file.path, sha256: entry.bakeValidation.file.sha256 },
            encode_receipt: { path: entry.encodeValidation.file.path, sha256: entry.encodeValidation.file.sha256 },
            selected_h264: {
              path: entry.encodeValidation.selected.path,
              bytes: entry.encodeValidation.selected.bytes,
              sha256: entry.encodeValidation.selected.sha256,
              crf: Number(entry.encodeValidation.candidate.crf),
              frame_count: entry.encodeValidation.frameCount,
              fast_start: entry.encodeValidation.fastStart,
            },
          })),
        }
    const selectedPostersReceipt = inputs.mode === 'single'
      ? {
          profile: options.posterProfile,
          opening: {
            path: prepared[0].selectedOpening.path,
            bytes: prepared[0].selectedOpening.bytes,
            sha256: prepared[0].selectedOpening.sha256,
          },
          terminal: {
            path: prepared[0].selectedTerminal.path,
            bytes: prepared[0].selectedTerminal.bytes,
            sha256: prepared[0].selectedTerminal.sha256,
          },
        }
      : prepared.map((entry) => ({
          profile: entry.variant.profile,
          poster_profile: options.posterProfile,
          opening: {
            path: entry.selectedOpening.path,
            bytes: entry.selectedOpening.bytes,
            sha256: entry.selectedOpening.sha256,
          },
          terminal: {
            path: entry.selectedTerminal.path,
            bytes: entry.selectedTerminal.bytes,
            sha256: entry.selectedTerminal.sha256,
          },
        }))
    const packetReceipt = {
      schema: 'bitterclip.iso4-artifact-packet-build.v1',
      script_version: SCRIPT_VERSION,
      created_at: new Date().toISOString(),
      mode: inputs.mode,
      inputs: packetInputs,
      tools: toolVersions,
      generation: {
        fingerprint: generationFingerprint,
        manifest_path: resolve(finalPacketDir, basename(generationPath)),
        source_revision: generation.source.revision,
      },
      audit_provenance: {
        repository_head: String(firstBake.repository?.head ?? ''),
        repository_branch: String(firstBake.repository?.branch ?? ''),
        revision_label: normalizedComponent(auditRevision, 'audit source revision'),
        renderer_inputs_sha256: rendererInputs.contentSha256,
        renderer_input_files: rendererInputs.files,
      },
      selected_posters: selectedPostersReceipt,
      source_bundle: {
        path: sourceBundle.path,
        bytes: sourceBundle.bytes,
        sha256: sourceBundle.sha256,
        private: true,
      },
      outputs: {
        asset_root: finalAssetRoot,
        release_packet: resolve(finalPacketDir, basename(packetPath)),
        marketing_manifest_candidate: resolve(finalPacketDir, basename(marketingPath)),
        poster_receipt: resolve(finalPacketDir, basename(posterReceiptPath)),
        source_bundle_receipt: resolve(finalPacketDir, basename(bundleReceiptPath)),
      },
      operator_scope: {
        account_public_id: options.accountPublicId,
        definition_key: options.definitionKey,
        asset_root: finalAssetRoot,
      },
      validation: {
        complete_bake: true,
        canonical_homepage: true,
        deterministic_bake: true,
        exact_master_hash: true,
        exact_candidate_hash: true,
        exact_candidate_probe: true,
        posters_from_selected_delivery_decode: true,
        lossless_poster_identity: true,
        deterministic_source_bundle: true,
        canonical_renderer_input_set: true,
        bake_renderer_inputs_match_bundled_bytes: true,
        content_addressed_cinematic_revision: true,
        shared_source_hash: true,
        shared_timeline: true,
        shared_renderer_contract: true,
        ...(inputs.mode === 'multi' ? {
          identified_source_revision: true,
          declared_source_inputs_clean: true,
          unrelated_worktree_changes_allowed: true,
        } : {}),
        declared_variant_order_preserved: true,
        every_asset_below_one_asset_root: true,
        product_release_schema: RELEASE_SCHEMA,
        product_generation_schema: GENERATION_SCHEMA,
      },
    }
    const packetReceiptPath = resolve(packetDir, 'packet-build-receipt.json')
    await writeFile(packetReceiptPath, `${JSON.stringify(packetReceipt, null, 2)}\n`, { flag: 'wx' })

    for (const entry of entries) {
      const stagedPath = resolve(staging, 'assets', relative(finalAssetRoot, entry.path))
      const stagedFile = await exactRegularFile(stagedPath, { inside: resolve(staging, 'assets') })
      if (stagedFile.bytes !== entry.asset.byte_size || await sha256(stagedPath) !== entry.asset.sha256) {
        throw new Error(`staged ASSET_ROOT bytes changed before handoff: ${entry.asset.name}`)
      }
    }
    await rename(staging, options.output)
    console.log(`Release packet: ${resolve(options.output, 'packet/release-packet.json')}`)
    console.log(`Marketing candidate: ${resolve(options.output, 'packet/marketing-manifest-candidate.json')}`)
    console.log(`Poster receipt: ${resolve(options.output, 'packet/poster-receipt.json')}`)
    console.log(`Source bundle: ${sourceBundle.path}`)
    console.log(`Variants: ${prepared.map((entry) => entry.variant.profile).join(', ')}`)
    console.log(`Generation fingerprint: ${generationFingerprint}`)
  } catch (error) {
    await rm(staging, { recursive: true, force: true })
    throw error
  }
}

function runSelfTest() {
  const checks = []
  const assert = (condition, label) => {
    if (!condition) throw new Error(`self-test failed: ${label}`)
    checks.push(label)
  }
  const assertRejects = (operation, pattern, label) => {
    let error = null
    try {
      operation()
    } catch (caught) {
      error = caught
    }
    assert(error instanceof Error && pattern.test(error.message), label)
  }
  const specPath = resolve(TMP_ROOT, 'self-test/variant-spec.json')
  const valid = {
    schema: VARIANT_SPEC_SCHEMA,
    variants: [
      {
        profile: 'mobile',
        media_query: '(max-width: 599px)',
        bake_receipt: 'mobile/bake.json',
        encode_receipt: 'mobile/encode.json',
        crf: 18,
      },
      {
        profile: 'wide',
        media_query: '(min-width: 960px)',
        bake_receipt: 'wide/bake.json',
        encode_receipt: 'wide/encode.json',
        candidate: 'wide/h264.mp4',
      },
    ],
  }
  const variants = normalizeVariantSpecDocument(valid, specPath)
  assert(variants.length === 2 && variants[0].profile === 'mobile' && variants[1].profile === 'wide', 'variant declaration order is preserved')
  assert(variants[0].selection.crf === 18 && variants[1].selection.candidate.endsWith('/wide/h264.mp4'), 'CRF and exact-candidate selections normalize')
  assertRejects(
    () => normalizeVariantSpecDocument({ ...valid, extra: true }, specPath),
    /unknown keys/,
    'unknown top-level variant-spec keys fail closed',
  )
  assertRejects(
    () => normalizeVariantSpecDocument({
      ...valid,
      variants: [valid.variants[0], { ...valid.variants[1], media_query: valid.variants[0].media_query }],
    }, specPath),
    /duplicate media queries/,
    'duplicate media queries fail closed',
  )
  assertRejects(
    () => normalizeVariantSpecDocument({
      ...valid,
      variants: [valid.variants[0], { ...valid.variants[1], profile: valid.variants[0].profile }],
    }, specPath),
    /duplicate profiles/,
    'duplicate profiles fail closed',
  )
  assertRejects(
    () => normalizeVariantSpecDocument({
      ...valid,
      variants: [valid.variants[0], { ...valid.variants[1], bake_receipt: valid.variants[0].bake_receipt }],
    }, specPath),
    /duplicate bake receipts/,
    'duplicate variant receipts fail closed before media work',
  )
  assertRejects(
    () => normalizeVariantSpecDocument({
      ...valid,
      variants: [{ ...valid.variants[0], candidate: 'also.mp4' }],
    }, specPath),
    /exactly one/,
    'ambiguous candidate selection fails closed',
  )
  const baseCli = {
    provided: new Set(['variantSpec', 'bakeReceipt']),
    variantSpec: resolve(TMP_ROOT, 'spec.json'),
    bakeReceipt: resolve(TMP_ROOT, 'bake.json'),
    accountPublicId: 'acct_00000000000000000000',
    output: resolve(TMP_ROOT, 'packet-self-test'),
    profile: 'wide',
    posterProfile: 'q92',
    definitionKey: 'homepage-iso4',
    definitionName: 'ISO4 homepage cinematic',
  }
  assertRejects(
    () => validateCli(baseCli),
    /cannot be combined/,
    'variant spec and single-profile options are mutually exclusive',
  )
  const tarEntries = [
    { path: 'bundle-manifest.json', bytes: Buffer.from('{"schema":"test"}\n') },
    { path: 'repository/app/scene.ts', bytes: Buffer.from('export const x = 1\n') },
  ]
  const firstTar = buildTar(tarEntries)
  const secondTar = buildTar(tarEntries)
  const firstGzip = gzipSync(firstTar, { level: 9, mtime: 0 })
  const secondGzip = gzipSync(secondTar, { level: 9, mtime: 0 })
  assert(firstTar.equals(secondTar) && firstGzip.equals(secondGzip), 'source archive bytes are deterministic')
  assert(gunzipSync(firstGzip).equals(firstTar), 'source archive gzip round trip is exact')
  const firstFingerprint = definitionFingerprint({ z: 1, a: { y: 2, x: 3 } })
  const secondFingerprint = definitionFingerprint({ a: { x: 3, y: 2 }, z: 1 })
  assert(firstFingerprint === secondFingerprint, 'manifest fingerprint is key-order invariant')
  const rendererInputFiles = ISO4_REQUIRED_RENDERER_INPUTS.map((entry, index) => ({
    ...entry,
    bytes: index + 1,
    sha256: String(index % 10).repeat(64),
  }))
  const rendererInputs = rendererInputReceiptFromEntries(rendererInputFiles)
  assert(
    validateRendererInputReceipt(rendererInputs).contentSha256 === rendererInputs.contentSha256,
    'canonical renderer-input receipt validates its exact content hash',
  )
  assertRejects(
    () => rendererInputReceiptFromEntries(rendererInputFiles.slice(1)),
    /expected/,
    'renderer-input omission fails closed',
  )
  assertRejects(
    () => rendererInputReceiptFromEntries([
      ...rendererInputFiles,
      { path: 'README.md', role: 'source', bytes: 1, sha256: 'a'.repeat(64) },
    ]),
    /expected/,
    'unrelated renderer-input addition fails closed',
  )
  assertRejects(
    () => validateRendererInputReceipt({ ...rendererInputs, contentSha256: 'f'.repeat(64) }),
    /does not match/,
    'renderer-input receipt cannot claim a stale aggregate hash',
  )
  const changedRendererInputs = rendererInputReceiptFromEntries(rendererInputFiles.map((entry, index) => (
    index === 0 ? { ...entry, sha256: 'f'.repeat(64) } : entry
  )))
  assert(
    changedRendererInputs.contentSha256 !== rendererInputs.contentSha256,
    'one renderer-input byte hash changes cinematic content identity',
  )
  const fakeValidation = [{
    variant: { profile: 'wide' },
    bakeValidation: { rendererInputs },
  }]
  const fakeBundleFiles = rendererInputFiles.map((entry) => ({
    ...entry,
    path: resolve(REPO_ROOT, entry.path),
    repositoryPath: entry.path,
  }))
  assert(
    verifyBakesMatchBundledRendererInputs(fakeValidation, fakeBundleFiles).contentSha256
      === rendererInputs.contentSha256,
    'packet validation compares canonical bake receipts with bundled bytes',
  )
  assertRejects(
    () => verifyBakesMatchBundledRendererInputs(fakeValidation, fakeBundleFiles.map((entry, index) => (
      index === 0 ? { ...entry, sha256: 'e'.repeat(64) } : entry
    ))),
    /does not match the bundled bytes/,
    'dirty or stale bundled renderer bytes fail closed',
  )
  const cinematicGeneration = {
    source: { revision: `marketing.iso4.${rendererInputs.contentSha256}` },
    render_contract: { renderer_inputs_sha256: rendererInputs.contentSha256 },
  }
  const firstAuditPacket = { generation: cinematicGeneration, audit: { repository_head: 'a'.repeat(40) } }
  const secondAuditPacket = { generation: cinematicGeneration, audit: { repository_head: 'b'.repeat(40) } }
  assert(
    definitionFingerprint(firstAuditPacket.generation) === definitionFingerprint(secondAuditPacket.generation)
      && firstAuditPacket.audit.repository_head !== secondAuditPacket.audit.repository_head,
    'unrelated repository HEAD is audit provenance, not generation identity',
  )
  const assetRoot = resolve(TMP_ROOT, 'packet/assets')
  assert(
    isInside(assetRoot, resolve(assetRoot, 'wide/video.mp4'))
      && !isInside(assetRoot, resolve(assetRoot, '../outside.mp4')),
    'one generated asset-root boundary rejects traversal',
  )
  return { schema: 'bitterclip.iso4-artifact-packet-self-test.v1', pass: true, checks }
}

const options = parseCli(process.argv.slice(2))
if (options.help) {
  console.log(usage)
} else if (options.selfTest) {
  console.log(JSON.stringify(runSelfTest(), null, 2))
} else {
  await main(options)
}
